css:
@import url("https://fonts.googleapis.com/css2?family=Bodoni+Moda:ital,opsz,wght@0,6..96,500;0,6..96,700;1,6..96,500&family=Jost:wght@400;500;600&display=swap");
:root{--chalk:#F2F2EF;--stone:#D9D6CF;--graphite:#232323;--olive:#5E6B30;--olive-l:#B7C38A;--white:#fff;--text:#2B2B2B;--muted:#6B6A66;--line:#CFCCC4;
--serif:"Bodoni Moda",Didot,Georgia,serif;--sans:"Jost",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1240px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);font-size:18px;line-height:1.65;color:var(--text);background:var(--chalk);-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-family:var(--serif);font-weight:500;margin:0;line-height:1.05;color:var(--graphite);letter-spacing:-.01em}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 28px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--olive-l);padding:10px;z-index:99}
:focus-visible{outline:2px solid var(--olive);outline-offset:3px}
.site-header{border-bottom:1px solid var(--line);background:var(--chalk);position:sticky;top:0;z-index:40}
.nav{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;height:82px}
.menu{display:flex;gap:28px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:500}.menu a:hover{color:var(--olive)}
.logo{font-family:var(--serif);font-size:28px;font-weight:700;text-decoration:none;letter-spacing:.02em;color:var(--graphite);text-align:center}
.nav-right{display:flex;justify-content:flex-end}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 28px;font-weight:500;text-decoration:none;border:1px solid var(--graphite);font-family:var(--sans);font-size:17px;cursor:pointer;transition:background .2s,color .2s}
.btn-dark{background:var(--graphite);color:#fff}.btn-dark:hover{background:var(--olive);border-color:var(--olive)}
.btn-line{background:transparent;color:var(--graphite)}.btn-line:hover{background:var(--graphite);color:#fff}
.burger{display:none;background:none;border:1px solid var(--graphite);padding:9px 11px;cursor:pointer}.burger span{display:block;width:20px;height:2px;background:var(--graphite);margin:4px 0}

.hero{padding:90px 0 0}
.hero h1{font-size:clamp(50px,8vw,124px);text-align:center;max-width:15ch;margin:0 auto}
.hero h1 em{color:var(--olive)}
.hero .lead{text-align:center;font-size:21px;color:var(--muted);max-width:52ch;margin:28px auto 34px}
.actions{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}
.trio{display:grid;grid-template-columns:1fr 1.3fr 1fr;gap:18px;margin-top:70px;align-items:end}
.trio img{width:100%;object-fit:cover}
.trio img:nth-child(1){aspect-ratio:3/4}.trio img:nth-child(2){aspect-ratio:4/5}.trio img:nth-child(3){aspect-ratio:3/4}

section{padding:120px 0}
.label{font-size:15px;font-weight:600;color:var(--olive);margin-bottom:14px;display:block}
.split{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:start}
h2{font-size:clamp(40px,5vw,70px)}
.statement{font-family:var(--serif);font-size:clamp(26px,2.6vw,36px);line-height:1.35;color:var(--graphite)}

.svc{border-top:1px solid var(--graphite)}
.svc article{display:grid;grid-template-columns:1fr 1.3fr;gap:40px;padding:34px 0;border-bottom:1px solid var(--line)}
.svc h3{font-size:clamp(28px,3vw,40px)}
.svc p{margin:0 0 10px;color:var(--muted)}
.svc small{font-size:15px;color:var(--graphite);font-weight:500}

.kit{background:var(--graphite);color:#cfcdc6}
.kit h2{color:#fff}.kit .label{color:var(--olive-l)}
.kit-grid{display:grid;grid-template-columns:repeat(12,1fr);gap:18px;margin-top:56px}
.k{background:#2E2E2E;padding:28px;min-height:230px;display:flex;flex-direction:column;justify-content:space-between}
.k small{font-size:14px;color:#9d9b95}
.k-logo{grid-column:span 5;background:#E9E4D8;color:#2B2B2B;align-items:center;justify-content:center;text-align:center}
.k-logo .mark{font-family:var(--serif);font-size:74px;font-weight:700;line-height:1;color:#3E4A22}
.k-logo .mark i{font-style:italic;color:#B5643C}
.k-type{grid-column:span 7}
.k-type .aa{font-family:var(--serif);font-size:96px;line-height:1;color:#fff}
.k-type p{font-size:18px;margin:10px 0 0;color:#e2e0da}
.k-colors{grid-column:span 7;flex-direction:row;padding:0;gap:0}
.sw{flex:1;padding:18px;display:flex;flex-direction:column;justify-content:flex-end;font-size:14px}
.k-photo{grid-column:span 5;padding:0}
.k-photo img{width:100%;height:100%;object-fit:cover}

.cases{display:grid;gap:80px}
.case{display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center}
.case:nth-child(even) figure{order:2}
.case figure{margin:0}.case img{width:100%;aspect-ratio:4/3;object-fit:cover}
.case h3{font-size:clamp(34px,3.6vw,50px);margin-bottom:14px}
.case p{color:var(--muted)}
.case dl{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:24px 0 0}
.case dt{font-size:14px;color:var(--muted)}.case dd{margin:0;font-family:var(--sans);font-weight:500;font-size:34px;color:var(--olive)}

.method{background:var(--stone)}
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin-top:56px;border-top:1px solid var(--graphite)}
.step{padding:26px 24px 0 0}
.step b{font-family:var(--serif);font-style:italic;font-size:22px;color:var(--olive);display:block;margin-bottom:8px}
.step h3{font-size:28px;margin-bottom:10px}.step p{color:#4f4e4a;font-size:17px;margin:0}

.logos{display:grid;grid-template-columns:repeat(5,1fr);border-top:1px solid var(--line);border-left:1px solid var(--line);margin-top:48px}
.logos span{border-right:1px solid var(--line);border-bottom:1px solid var(--line);padding:34px 10px;text-align:center;font-family:var(--serif);font-size:22px;color:#55534e}
.logos span:nth-child(3n){font-family:var(--sans);font-weight:600;letter-spacing:.08em}

.quote{text-align:center}
.quote p{font-family:var(--serif);font-style:italic;font-size:clamp(28px,3.4vw,46px);line-height:1.3;max-width:26ch;margin:0 auto 24px;color:var(--graphite)}
.quote cite{font-style:normal;color:var(--muted)}

.packs{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border:1px solid var(--graphite);margin-top:56px}
.pack{padding:36px;border-right:1px solid var(--graphite);display:flex;flex-direction:column;background:var(--chalk)}
.pack:last-child{border-right:0}.pack.hot{background:#fff}
.pack h3{font-size:34px}.pack .amt{font-family:var(--serif);font-size:44px;margin:12px 0 0;color:var(--olive)}
.pack .amt small{font-family:var(--sans);font-size:16px;color:var(--muted)}
.pack ul{padding-left:18px;margin:18px 0 28px;color:#4f4e4a}.pack li{margin-bottom:8px}
.pack .btn{margin-top:auto;justify-content:center}

.faq details{border-bottom:1px solid var(--line);padding:22px 0}
.faq summary{list-style:none;cursor:pointer;font-family:var(--serif);font-size:24px;display:flex;justify-content:space-between;gap:18px}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";font-family:var(--sans);font-size:26px;color:var(--olive);line-height:1}
.faq details[open] summary::after{content:"−"}.faq details p{margin:12px 0 0;color:var(--muted)}

.contact{background:var(--olive);color:#eef0e4}
.contact h2{color:#fff}.contact .label{color:var(--olive-l)}
.contact a{color:#fff}
form{background:var(--chalk);padding:34px;color:var(--text)}
label{display:block;font-weight:600;font-size:15px;margin-bottom:6px}
input,select,textarea{width:100%;font:inherit;font-size:17px;padding:12px 14px;border:1px solid var(--line);margin-bottom:16px;background:#fff;color:var(--text);border-radius:0}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--graphite)}
form .btn{width:100%;justify-content:center}
footer{background:var(--graphite);color:#a8a6a0;padding:56px 0 28px;font-size:16px}
.foot{display:flex;justify-content:space-between;gap:30px;flex-wrap:wrap;align-items:end;margin-bottom:34px}
footer .logo{color:#fff;font-size:44px;text-align:left}
footer ul{list-style:none;padding:0;margin:0;display:flex;gap:24px;flex-wrap:wrap}footer a{text-decoration:none}footer a:hover{color:#fff}
.legal{border-top:1px solid #3a3a3a;padding-top:20px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:15px}
@media (max-width:1000px){.nav{grid-template-columns:auto 1fr auto}.menu,.nav-right .btn{display:none}.burger{display:block}.logo{text-align:left}
.menu.open{display:flex;flex-direction:column;position:absolute;top:82px;left:0;right:0;background:var(--chalk);padding:22px 28px;border-bottom:1px solid var(--line);gap:16px}
.split,.case{grid-template-columns:1fr;gap:34px}.case:nth-child(even) figure{order:0}
.svc article{grid-template-columns:1fr;gap:10px}
.k-logo,.k-type,.k-colors,.k-photo{grid-column:span 12}.k-photo{height:300px}
.steps{grid-template-columns:1fr 1fr;row-gap:30px}.packs{grid-template-columns:1fr}.pack{border-right:0;border-bottom:1px solid var(--graphite)}.pack:last-child{border-bottom:0}
.logos{grid-template-columns:repeat(3,1fr)}}
@media (max-width:600px){body{font-size:17px}section{padding:80px 0}.trio{grid-template-columns:1fr}.trio img:not(:nth-child(2)){display:none}.steps{grid-template-columns:1fr}.logos{grid-template-columns:1fr 1fr}.k-colors{flex-direction:column;min-height:auto}.sw{min-height:70px}}
